// TH18 v1.00a Stage 6 Boss4 non-spell (st06bs.ecl.txt:392-450; helper 184-232).
// Source t0 = B:407 timerReset; slot-0 interrupt B:428 HP2700 / timeout 3000 ->
// BossCard4 at B:1085, which is only the segment boundary, not transcribed here.
// Training shell: controller enemy at (0,0) with body collision off; the real boss
// keeps source hurtbox/hitbox and source position (0,128); 120-frame opening buffer.
const TIME_LIMIT: int = 3122;    // 120 buffer + 3000 source timeout + ~2 task-phase frames
const SOURCE_LIMIT: int = 3000;  // B:428 setInterrupt slot0 timeout
const OPENING_BUFFER: int = 120;
const HP_THRESHOLD: int = 2700;  // B:428 setInterrupt slot0 HP threshold

const TH18_TALISMAN: int = 528;  // TH18 type 11 Talisman, base radius 2.8

// B:193-195: ANIM a=1 birth retraction is expressed as sh_dist(-4*initial speed);
// WAIT 0x80000000 a=20; VELTIME 0x200000 a=60, r=%L, s=-9999994 (keep entry angle).
// The ramped quantity is the source logical scalar speed 1 -> target over 60 frames.
xformdef TALISMAN_MOTION(target: fx) {
    wait(20);
    step_speed(target, 60 + 65536 * EASE_LINEAR);
}

// B:184-232 Boss1_at. Each async instance is a private target task, so its
// emitter slot 0 replaces the source per-call et slot B (2/0/1). Callers:
// B:436 / B:437 common, B:439 Hard and B:441 Lunatic third stream.
async sub at_wave(color: int, c0: angle, d0: angle, de: angle, df: angle,
                  radius: fx, axis: angle, dh: angle, ratio: fx,
                  count: int, target: fx) {
    var rank: int = global(GVAR_RANK);
    // B:196-202: Easy doubles E/F; Normal scales both by 1.2; H/L keep source values.
    var de_i: int = de as int;
    var df_i: int = df as int;
    if rank == 0 { de_i = de_i * 2; df_i = df_i * 2; }
    if rank == 1 { de_i = de_i * 6 / 5; df_i = df_i * 6 / 5; }
    var dc: angle = de_i as angle;
    var dd: angle = df_i as angle;
    // B:218-227: Easy waits 2; Normal/Hard/Lunatic wait 1.
    var step: int = 1;
    if rank == 0 { step = 2; }

    sh_reset(0);
    sh_sprite(0, TH18_TALISMAN, color); // etSprite(B,11,A)
    sh_aim(0, 0);                       // etAim(B,1): N=1 fixed direction
    sh_ring(0, 0);
    sh_count(0, 1, 1);                  // etCount(B,1,1)
    sh_speed(0, 1fx, 0fx);              // etSpeed(B,1,1): single layer s0=1
    sh_dist(0, -4fx);                   // ANIM a=1: -4*initial speed
    sh_xform(0, TALISMAN_MOTION(target));

    for i in 0..count {
        // B:208 ins_94(M,N,D,G,H,J): phi=D, radius=G, axis=H, ratio=J.
        // Source validRad keeps one-turn state; mirror it in BAM integers.
        var phi: int = (d0 as int) % 65536;
        if phi > 32767 { phi = phi - 65536; }
        if phi < -32768 { phi = phi + 65536; }
        var hi: int = (axis as int) % 65536;
        if hi > 32767 { hi = hi - 65536; }
        if hi < -32768 { hi = hi + 65536; }
        var ti: int = phi - hi;
        ti = ti % 65536;
        if ti > 32767 { ti = ti - 65536; }
        if ti < -32768 { ti = ti + 65536; }
        var t: angle = ti as angle;
        var u: fx = radius * ratio * cos(t);
        var v: fx = radius * sin(t);
        var m: fx = u * cos(axis) - v * sin(axis);
        var n: fx = u * sin(axis) + v * cos(axis);
        // B:209-210: H += I and validRad(H) before the next offset.
        var ai: int = (axis + dh) as int;
        ai = ai % 65536;
        if ai > 32767 { ai = ai - 65536; }
        if ai < -32768 { ai = ai + 65536; }
        axis = ai as angle;
        sh_offset(0, m, n);    // etOffset(B,M,N) relative to the real boss
        sh_angle(0, c0, 0deg); // etAngle(B,C,0)
        sh_fire(0);            // etOn(B)
        // B:214-217: C += E, D += F, validRad on both.
        var ci: int = (c0 + dc) as int;
        ci = ci % 65536;
        if ci > 32767 { ci = ci - 65536; }
        if ci < -32768 { ci = ci + 65536; }
        c0 = ci as angle;
        var di: int = (d0 + dd) as int;
        di = di % 65536;
        if di > 32767 { di = di - 65536; }
        if di < -32768 { di = di + 65536; }
        d0 = di as angle;
        wait(step);
    }
}

// B:404 moveLimit(0,128,280,64): x in [-140,140], y in [96,160]; direction-
// selection inner region x +-70, y 112..144 (center +- width/height / 4).
// B:444 moveRand(100,0,0.6): speed 0.6*(1-k/100), k=1..100.
// Shared slots: self_int(0)=next step count, self_fx(0/1)=logical unit vector.
sub move_arm(duration: int, speed0: fx) {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < duration { speed = speed0 * ((duration - k) as fx) / (duration as fx); }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

// The main task arms k=1 at the moveRand call; this task continues k=2..duration,
// so the first source movement tick is not delayed by the async first-run frame.
async sub move_continue(duration: int, speed0: fx) {
    loop {
        move_arm(duration, speed0);
        if self_int(0) >= duration { return; }
        wait(1);
    }
}

sub card_move_rand() {
    // B:444 moveRand: R = pi*U -> BAM r; branch logic per movement.md.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; } // source explicitly normalizes this branch
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3; // source WORD modulo3, with its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
        // Do not normalize this branch before the source fabs tests.
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05rad (nearest BAM boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    move_arm(100, 0.6fx);
}

// B:392-450 Boss4. B:430 wait90 and B:432 wait80 are the 170-frame prelude.
// Cycle B:434-447: two common async streams plus a third only on Hard/Lunatic;
// then wait600, moveRand, wait60. The successor at B:1085 is only the boundary.
async sub pattern() {
    wait(OPENING_BUFFER); // training buffer before source t0
    wait(90);             // B:430
    wait(80);             // B:432 (B:431 EffChargePoint3 is presentation)
    var rank: int = global(GVAR_RANK);
    var l3: fx = 3.5fx;
    if rank == 3 { l3 = 3.8fx; } // B:439 Hard 3.5, B:441 Lunatic 3.8
    loop {
        spawn at_wave(14, 90deg, 0deg, 3.5deg, 7.1deg, 64fx, -90deg,
                      2deg, 0.5fx, 600, 1.5fx); // B:436
        spawn at_wave(13, 180deg, -90deg, 6deg, 3.6deg, 64fx, 90deg,
                      -3deg, 0.5fx, 600, 3.0fx); // B:437
        if rank >= 2 {
            spawn at_wave(2, -90deg, 180deg, -5deg, 4.6deg, 64fx, 90deg,
                          3deg, 0.5fx, 600, l3); // B:439/441
        }
        wait(600);        // B:443
        card_move_rand(); // B:444
        spawn move_continue(100, 0.6fx);
        wait(60);         // B:445
    }
}

async sub boss_main() {
    // B:33-35 boxes are inherited from the common boss entry; B:14
    // movePos(0,128) is the canonical source entry position for this segment.
    // The invulnerable shell fixes the segment window at the source timeout.
    set_invuln(65535);
    set_hurtbox(20fx); // source hurtbox 40x40
    set_hitbox(24fx);  // source hitbox 48x48
    phase_begin(0, pattern, TIME_LIMIT, HP_THRESHOLD);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

// Extra training-only phase controller at (0,0); it never carries source judgement.
async sub controller() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    _ = spawn_enemy(0fx, 128fx, 18700, 0, 0, 0, boss_main);
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, controller);
    loop { wait(600); }
}
